/* 字符串谱树 → 查找树:节点 = { w: 子树谱线数, fam: 族下标|null, c: { 4字符着法: 子节点 } } */
function build(s) {
  const root = { w: 0, fam: null, c: {} };
  const stack = [root];
  let i = 0;
  while (i < s.length) {
    if (s[i] === ')') { stack.pop(); i++; continue; }
    const key = s.slice(i, i + 2); i += 2;
    const w = parseInt(s.slice(i, i + 2), 36); i += 2;
    let fam = null;
    if (s[i] === '+') { fam = parseInt(s.slice(i + 1, i + 3), 36); i += 3; }
    const node = { w, fam, c: null };
    stack[stack.length - 1].c[key] = node;      // 先挂到父节点
    if (s[i] === '(') { node.c = {}; stack.push(node); i++; }      // 有子树再入栈
  }
  return root;
}
export const ROOT = build(TREE);

/* 4字符着法(坐标串)↔ 树键(2字符 AL 编码)换算 */
const encKey = (k) => AL[sqOf(k.slice(0, 2))] + AL[sqOf(k.slice(2, 4))];
const decKey = (k) => {
  const a = AL.indexOf(k[0]), b = AL.indexOf(k[1]);
  return 'abcdefgh'[a & 7] + (8 - (a >> 3)) + 'abcdefgh'[b & 7] + (8 - (b >> 3));
};
const sqOf = (s) => 'abcdefgh'.indexOf(s[0]) + (8 - Number(s[1])) * 8;

/** 调试 / 测试用:某局面的全部谱内候选(带子树权重与开局族名) */
export function bookCandidates(seqKeys) {
  let node = ROOT;
  for (const k of seqKeys) {
    node = node.c && node.c[encKey(k)];
    if (!node) return null;
  }
  if (!node.c) return null;
  return Object.entries(node.c).map(([key, c]) => ({ move: decKey(key), name: c.fam != null ? NFAM[c.fam] : null, w: c.w }));
}

/** 已走着法序列(如 ['e2e4','e7e5'])→ 下一手候选;
 * 返回 { move: 'e2e4', name: 'Ruy Lopez'|null } 或 null(无谱可循)。
 * name 仅在该着进入已命名的开局族时给出,其余候选一律无名(显示"开局库")。 */
export function bookResponse(seqKeys) {
  let node = ROOT;
  for (const k of seqKeys) {
    node = node.c && node.c[encKey(k)];
    if (!node) return null;
  }
  if (!node.c) return null;                       // 该谱已走完,不再提供候选
  const kids = Object.entries(node.c);
  if (!kids.length) return null;                  // 空树兜底
  let sum = 0;
  for (const [, c] of kids) sum += c.w;
  let t = Math.random() * sum;
  for (const [key, c] of kids) {
    t -= c.w;
    if (t <= 0) return { move: decKey(key), name: c.fam != null ? NFAM[c.fam] : null };
  }
  const [key, c] = kids[0];                       // 浮点边界兜底
  return { move: decKey(key), name: c.fam != null ? NFAM[c.fam] : null };
}

/** 当前局面查谱:把谱着坐标绑定到 pos 的合法着法(升变取升后),书着不合法视为无谱;
 * 返回 { move: 完整着法(mkMove 编码), name: string|null } 或 null。 */
export function bookMove(pos, seqKeys) {
  const hit = bookResponse(seqKeys);
  if (!hit) return null;
  const from = sqOf(hit.move.slice(0, 2)), to = sqOf(hit.move.slice(2, 4));
  const buf = new Int32Array(256);
  const n = genLegal(pos, buf);
  for (let i = 0; i < n; i++) {
    if (mFrom(buf[i]) !== from || mTo(buf[i]) !== to) continue;
    const pr = mPromo(buf[i]);
    if (pr && pr !== QUEEN) continue;
    return { move: buf[i], name: hit.name };
  }
  return null;
}
